param([string] $Label = 'screen')
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
Push-Location (Join-Path $repo 'Ignore/Benchmarks/excel-csv-broad/compare')
try {
    foreach ($framework in 'net10.0','net8.0') {
        $env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot $framework
        $env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'screen-cases.json'
        $env:OFFICEIMO_COMPARISON_MASK = '65535'
        $env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
        $env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
        dotnet (Join-Path $repo "Ignore/Benchmarks/excel-csv-broad/compare/bin/Release/$framework/Compare.dll") --filter '*SnapshotComparison*' --warmupCount 24 --iterationCount 8 --invocationCount 4 --unrollFactor 1 --outliers DontRemove --artifacts (Join-Path $PSScriptRoot "$Label-native-$framework") *> (Join-Path $PSScriptRoot "$Label-native-$framework.log")
        if ($LASTEXITCODE) { throw "Native screening failed: $framework" }
        $report = Get-Content (Join-Path $PSScriptRoot "$Label-native-$framework/results/SnapshotComparison-report-full.json") -Raw | ConvertFrom-Json
        if ($report.Benchmarks.Count -ne 44 -or @($report.Benchmarks | Where-Object { $_.Statistics.N -ne 8 }).Count) { throw "Incomplete native screening: $framework" }
        Write-Output "Completed 44 measured screening cases in $framework."
    }
} finally { Pop-Location }
foreach ($mask in 65535L,4294901760L) {
    pwsh -NoProfile -File (Join-Path $PSScriptRoot 'rotated.ps1') -Mask $mask -Label "$Label-rotated" *> (Join-Path $PSScriptRoot "$Label-rotated-$mask.log")
    if ($LASTEXITCODE) { throw "Screening rotation failed: $mask" }
    Write-Output "Completed 22 workload rotations: $mask"
}

Reproduction.Rotated:
param([long] $Mask = 65535, [int] $Iterations = 24, [int] $Warmup = 32, [int] $Operations = 4,
    [string] $Cases = 'screen-cases.json', [string] $Label = 'screen-rotated', [switch] $IdenticalBaseline)
$ErrorActionPreference = 'Stop'
Import-Module PSPublishModule
$env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot 'net10.0'
$env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot $Cases
$env:OFFICEIMO_PERFORMANCE_AA = if ($IdenticalBaseline) { '1' } else { '0' }
$env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
[Diagnostics.Process]::GetCurrentProcess().ProcessorAffinity = [IntPtr]::new($Mask)
[Diagnostics.Process]::GetCurrentProcess().PriorityClass = 'Normal'
[Reflection.Assembly]::LoadFrom((Join-Path (Split-Path $PSScriptRoot -Parent) 'excel-csv-broad/compare/bin/Release/net10.0/Compare.dll')) | Out-Null
$global:BufferProbes = @{}
$global:BufferExpected = @{}
$global:BufferOperations = $Operations
foreach ($key in [SnapshotProbe]::Keys()) {
    $before = [SnapshotProbe]::Load($key, 'baseline')
    $after = [SnapshotProbe]::Load($key, 'candidate')
    [SnapshotProbe]::ValidateEquivalent($before, $after)
    $global:BufferProbes[$key] = @{ Before = $before; After = $after }
    $global:BufferExpected[$key] = @{ Before=$before.ExpectedResult; After=$after.ExpectedResult }
}
try {
    Invoke-BenchmarkSuite -OutputRoot (Join-Path $PSScriptRoot "$Label-$Mask") -WarmupCount $Warmup -IterationCount $Iterations -RunOrder Rotated -OutlierMode None -Settings {
        New-BenchmarkSuite 'CSV writer buffer qualification' {
            Add-BenchmarkMetadata AffinityMask $Mask
            Add-BenchmarkMetadata OperationsPerSample $Operations
            Add-BenchmarkMetadata IdenticalBaseline ([string]$IdenticalBaseline)
            Add-BenchmarkMetadata Runtime ([System.Runtime.InteropServices.RuntimeInformation]::FrameworkDescription)
            Add-BenchmarkMetadata Priority ([Diagnostics.Process]::GetCurrentProcess().PriorityClass.ToString())
            Add-BenchmarkCaseSource @($global:BufferProbes.Keys | Sort-Object | ForEach-Object { [pscustomobject]@{Name=$_} })
            Set-BenchmarkSetup {
                param($case, $run)
                $run.Probe = $global:BufferProbes[$case.Scenario][$case.Engine]
                $run.Expected = $global:BufferExpected[$case.Scenario][$case.Engine]
            }
            foreach ($engine in 'Before','After') {
                Add-BenchmarkEngine $engine {
                    Add-BenchmarkOperation WriteBatch {
                        param($case, $run)
                        for ($i=0; $i -lt $global:BufferOperations; $i++) { $run.Result = $run.Probe.RunSynchronously() }
                    }
                }
            }
            Add-BenchmarkValidation {
                param($case, $run)
                if ($run.Result.ToString() -ne $run.Expected) { throw 'Output length differs from this build''s independently validated CSV.' }
            }
            Add-BenchmarkComparison -Baseline Before -Metric MeanMs,MedianMs -TieTolerance 0.05
        }
    }
} finally {
    foreach ($pair in $global:BufferProbes.Values) { $pair.Before.Dispose(); $pair.After.Dispose() }
}

Reproduction.Prepare:
$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
Set-Location $repo
foreach ($framework in 'net10.0','net8.0') {
    dotnet build OfficeIMO.CSV/OfficeIMO.CSV.csproj -c Release -f $framework --no-restore --nologo -v minimal *> (Join-Path $PSScriptRoot "candidate-build-$framework.log")
    if ($LASTEXITCODE) { throw "Candidate build failed: $framework" }
    foreach ($file in 'OfficeIMO.CSV.dll','OfficeIMO.CSV.pdb') {
        Copy-Item -LiteralPath (Join-Path $repo "OfficeIMO.CSV/bin/Release/$framework/$file") -Destination (Join-Path $PSScriptRoot "$framework/candidate-csv/$file")
    }
    $provenance = Get-Content (Join-Path $PSScriptRoot "baseline-final-provenance-$framework.json") -Raw | ConvertFrom-Json
    foreach ($item in $provenance.Manifest) {
        $item.After = (Get-FileHash (Join-Path $PSScriptRoot "$framework/candidate-csv/$($item.File)")).Hash
        if ($item.File -ne 'OfficeIMO.CSV.dll' -and $item.After -ne $item.Before) { throw "Unexpected differing workload/dependency snapshot DLL: $framework/$($item.File)" }
    }
    $provenance | ConvertTo-Json -Depth 10 | Set-Content (Join-Path $PSScriptRoot "candidate-provenance-$framework.json") -Encoding utf8
    $env:OFFICEIMO_PERFORMANCE_SNAPSHOTS = Join-Path $PSScriptRoot $framework
    $env:OFFICEIMO_COMPARISON_CASES = Join-Path $PSScriptRoot 'conformance-cases.json'
    $env:OFFICEIMO_BENCHMARK_PROCESS_PRIORITY = 'Normal'
    $env:OFFICEIMO_BENCHMARK_OUTPUT = Join-Path $PSScriptRoot 'files'
    dotnet (Join-Path $repo "Ignore/Benchmarks/excel-csv-broad/compare/bin/Release/$framework/Compare.dll") --validate *> (Join-Path $PSScriptRoot "candidate-conformance-$framework.log")
    if ($LASTEXITCODE) { throw "Candidate output conformance failed: $framework" }
    Write-Output "Validated before/after 312 API outputs in $framework; only the product DLL differs."
}
git diff --full-index --binary --no-ext-diff --no-textconv --no-color --output=Ignore/Benchmarks/csv-writer-buffers/candidate.patch -- OfficeIMO.CSV
if ($LASTEXITCODE) { throw 'Cannot record candidate diff.' }
(Get-FileHash (Join-Path $PSScriptRoot 'candidate.patch')).Hash | Set-Content (Join-Path $PSScriptRoot 'candidate-patch.sha256')

